      "AWS" : "arn:${AWS::Partition}:iam::${AWS::AccountId}:root"
    },
    "Action" : "kms:*",
    "Resource" : "*"
  }, {
    "Sid" : "Allow EventBridge to use kms operations",
    "Effect" : "Allow",
