    "Resource" : "*",
    "Condition" : {
      "StringEquals" : {
        "kms:EncryptionContext:aws:events:event-bus:arn" : "arn:${AWS::Partition}:events:${AWS::Region}:${AWS::AccountId}:event-bus/default"
      }
    }
  }, {
    "Sid" : "Allow EventBridge to call kms:DescribeKey",
    "Effect" : "Allow",
    "Principal" : {
      "Service" : "events.amazonaws.com"
    },
    "Action" : "kms:DescribeKey",
    "Resource" : "*"
  } ]
}
